"""Content of RADION (Markdown + LaTeX): the radion of 7+1 spacetime -- the size of the four extra dimensions as a four-dimensional field --
defined precisely and explained for students, with worked examples in which the four extra dimensions are a 4-torus (the auxiliary space of
7+1.nb) or a 4-sphere, and a statement-by-statement check of the author's note on the radion.  The examples are checked in section 26 of the
evaluated 7+1.nb and by tools/ref_radion.py; the results quoted from sections 20-25 are parsed from the evaluated notebook.  Every
equation used is written in this document."""
from docgen import Doc
from doc_stage3_common import fmt, nums_in
import doc_radion_common as R
import doc_torus_brane_common as TB
from doc_torus import basis_checks

BASIS = [('cp', 'stabilizing potential: W'), ('cp', 'radion equation of Einstein gravity'), ('cp', 'radion mass:'),
         ('cp', 'static auxiliary space: (kappa/4)'), ('cp', 'Einstein-frame form of the constraint'), ('cp', 'Kasner constants'),
         ('cp', 'without the stabilizing potential the gas-dominated'), ('cp', 'capture:'), ('cp', 'through brane fields alone'),
         ('cp', 'the radion decays into the bulk'), ('cp', 'radion equilibrium in de Sitter'), ('cp', 'eight-dimensional de Sitter'),
         ('sm', 'ADD relation'), ('tb', 'the auxiliary torus today'), ('tb', 'graviton + radion')]


def build(D, today):
    nck, nok, nrb, nrok = R.counts(D)
    rb = [(k, v) for k, v in D['ref'].get('rd', ('', '', {}))[2].items() if v in ('True', 'False')]
    cmp_ = R.compare(D); wst = R.worst(D)
    v = lambda key, i, n=6: R.val(D, key, i, n)
    iv = lambda key, i: R.ival(D, key, i)
    tod = R.nbv(D, 'today'); ttb = TB.nbv(D, 'today')
    g = TB.g
    radnow = TB.cp(D, 'radnow'); capfit = TB.cp(D, 'capfit'); cap0 = TB.cp(D, 'cap0'); late = TB.cp(D, 'late'); pq = TB.cp(D, 'pq')
    decay = TB.cp(D, 'decay'); bulk = TB.cp(D, 'bulk'); hinf = TB.cp(D, 'hinf'); dsv = TB.cp(D, 'ds')

    d = Doc('The radion of 7+1 spacetime',
            'The size of the four extra dimensions as a field in ordinary spacetime — on the 4-torus and on the 4-sphere; a guide for students, '
            'with worked examples checked in section 26 of the notebook 7+1.nb and by an independent Python program, and a check of the author’s '
            'note on the radion',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1), evaluated ' + D['log'].get('finished', ''),
             'Document generated by tools/make_docs.py on ' + today],
            'The four extra space-like coordinates $x_4,\\dots,x_7$ of the 7+1 model describe a small compact space. Its overall SIZE can vary from '
            'place to place and from time to time in ordinary spacetime; seen from four dimensions this size is a scalar field, the RADION. This '
            'document defines the radion precisely — through the Einstein-frame metric $ds^2=e^{-4\\beta(x)}g_{E\\mu\\nu}dx^\\mu dx^\\nu-e^{2\\beta(x)}\\gamma_{ij}dy^idy^j$, '
            'whose field $\\beta=\\ln(b/b_0)$ has the canonical form $\\phi=\\sqrt{12}\\,M_{\\rm Pl}\\beta$ — and works out, for two choices of the extra '
            'space, the 4-TORUS $T^4$ of 7+1.nb and the 4-SPHERE $S^4$, everything that follows from it: the reduced action, the potential and the '
            'mass of the radion (the torus is a modulus, the sphere is not), how the radion couples to the world brane and to the Higgs boson, the '
            'fifth force and the Eöt-Wash bound, the Kaluza–Klein levels and the Dirac zero modes of dirac16complex on the two spaces, and the '
            'contrast with the warped radion of Randall and Sundrum. It checks, statement by statement, a note of the author on the radion and '
            'corrects what the checks require (a factor 2 in the canonical normalization, the Einstein-frame factor of a bulk potential, the signs '
            'of the brane tensions, the normalization constant and the mass of the warped radion, the five-dimensional equations offered for eight '
            'dimensions). Every equation used is written here. Section 26 of 7+1.nb contains %d checks (%d True); the independent program '
            'tools/ref_radion.py contains %d (%d True); the %d groups of numbers printed by both agree to a largest relative difference of %s.'
            % (nck, nok, nrb, nrok, len(cmp_), fmt(wst, 2) if wst is not None else '?'))

    # ==============================================================================================
    d.h1('1. Results at a glance')
    d.table(['question', 'answer', 'where'], [
        ['What is the radion?', 'the field $\\beta(x)=\\ln(b/b_0)$ (torus) or $\\ln(r/r_0)$ (sphere) that measures the size of the extra space at the point $x$ '
         'of ordinary spacetime; canonical form $\\phi=\\sqrt{12}\\,M_{\\rm Pl}\\beta$', '§4'],
        ['Why the factor $e^{-4\\beta}$ in front of $g_E$?', 'it keeps the coefficient of the four-dimensional curvature constant (EINSTEIN FRAME): '
         '$e^{2\\cdot(-2\\beta)}e^{4\\beta}=1$; in general $2\\alpha+n\\beta=0$', '§4.2'],
        ['What is its kinetic term?', '$6M_{\\rm Pl}^2(\\partial\\beta)^2=\\frac12(\\partial\\phi)^2$; for $n$ extra dimensions $\\frac{M_{\\rm Pl}^2}2\\,\\frac{n(n+2)}2\\,(\\partial\\beta)^2$ '
         '— coefficients %s, %s, %s, %s for $n=1,\\dots,4$' % (v('kin', 0, 3), v('kin', 1, 3), v('kin', 2, 3), v('kin', 3, 3)), '§4.3, §4.5'],
        ['What is the physical volume?', '$V=V_0e^{4\\beta}=V_0e^{2\\phi/(\\sqrt3M_{\\rm Pl})}$; $V_0=b_0^4L_c^4$ ($T^4$) or $\\frac{8\\pi^2}3r_0^4$ ($S^4$)', '§4.4'],
        ['Does it have a potential?', 'on $T^4$ with $\\Lambda=0$: no — a MODULUS; on $S^4$ the curvature gives $-6M_{\\rm Pl}^2e^{-6\\beta}/r_0^2$; the bulk '
         'cosmological constant gives $M_{\\rm Pl}^2\\Lambda e^{-4\\beta}$', '§6'],
        ['How is it stabilized, and how heavy is it?', '$T^4$: $\\Lambda+\\kappa U_0=0$, $U_1=0$, $m_r^2=\\kappa K_U/12$. $S^4$: $(\\Lambda+\\kappa U_0)r_0^2=%s$, '
         '$\\kappa U_1r_0^2=%s$, $m_r^2=\\kappa K_U/12%s/r_0^2$' % (iv('sphU', 0), iv('sphU', 1), iv('sphU', 2)), '§6.3–6.4'],
        ['Can the sphere be held by $\\Lambda$ alone?', 'only at a maximum: $dS_4\\times S^4$ with $\\Lambda r_0^2=%s$, $H^2r_0^2=%s$, $m^2=%s\\,H^2$ (unstable); a '
         '4-form flux can hold it: $\\Lambda r_0^2=%s$, $\\kappa\\rho_Fr_0^2=%s$, $m^2r_0^2=%s$' % (iv('sphL', 0), iv('sphL', 1), iv('sphL', 2), v('sphF', 0, 3),
                                                                                                        v('sphF', 1, 3), iv('sphF', 2)), '§6.5–6.6'],
        ['How does it couple to the world brane?', 'through $h_{\\mu\\nu}=e^{-4\\beta}g_{E\\mu\\nu}$, on $T^4$ and $S^4$ alike: '
         '$\\mathcal L=\\frac{\\phi}{\\sqrt3M_{\\rm Pl}}T^\\mu{}_\\mu$; a massless radion adds a fifth force of strength $\\frac23$', '§7.1–7.2'],
        ['How heavy must it be?', 'Eöt-Wash: heavier than about $\\hbar c/38.6\\,\\mu$m $=%s$ meV; the radion of 7+1.nb ($m_r=10$ GeV) has the range $%s$ m'
         % (fmt(R.nbv(D, 'ew')[0]*1e3, 4) if R.nbv(D, 'ew') else '?', v('ew', 1, 4)), '§7.2'],
        ['Does it mix with the Higgs boson?', 'yes, through $\\xi R(h)H^\\dagger H$ on the brane, with $\\gamma=v/(\\sqrt3M_{\\rm Pl})=%s$: for $\\xi=1$, $m_{r0}=10$ GeV '
         'the mixing angle is $%s$ and the Higgs rates change by $%s$ — unobservable' % (v('ew', 2, 4), v('hr71', 1, 3), v('hr71', 3, 2)), '§7.3'],
        ['Torus or sphere — what changes?', 'levels $2\\pi|\\vec n|/\\ell_\\perp$ versus $\\sqrt{l(l+3)}/r$; the brane couples to $r_4(k)$ states per torus level '
         'and to ONE zonal state per sphere level; dirac16complex has zero modes on $T^4$ and none on $S^4$ (lowest $|\\lambda|=2/r$)', '§8'],
        ['Flat or warped?', 'in 7+1 (unwarped) the radion couples with $1/(\\sqrt3M_{\\rm Pl})$; in Randall–Sundrum with $1/\\langle\\mu\\rangle$, $%s$ times '
         'stronger for $\\langle\\mu\\rangle=3$ TeV' % v('strength', 0, 3), '§9'],
        ['What does the check of the note find?', 'its ideas hold; the checks correct a factor 2 in the canonical normalization, a missing '
         'Einstein-frame factor, the sign of a junction condition (and so of the brane tensions), $f_\\mu$ and the warped radion mass, mixed '
         'normalizations, five-dimensional equations used in eight dimensions, and an incomplete kinetic Lagrangian of the Higgs–radion mixing', '§11'],
    ], widths=[0.25, 0.62, 0.13])

    # ==============================================================================================
    d.h1('2. Conventions')
    d.ul(['Coordinates $X=(x_0,\\dots,x_7)$: $x_0$ is time — the direction of the octonion unit $e_0=1$; $x_1,x_2,x_3$ are ordinary space; '
          '$x_4,x_5,x_6,x_7$ are the four extra (auxiliary) space-like coordinates. Ordinary spacetime points are written $x=(x_0,\\dots,x_3)$, '
          'points of the extra space $y=(x_4,\\dots,x_7)$; Greek indices $\\mu,\\nu$ run over $0,\\dots,3$, Latin $i,j$ over $4,\\dots,7$, capital $A,B$ '
          'over $0,\\dots,7$.',
          'The flat metric is $\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$: simply the squares of the octonion basis, $e_0^2=+1$, $e_k^2=-1$. The signature is '
          '"mostly minus"; xAct declares the spacetime with the signature list $\\{7,1,0\\}$: seven space-like and one time-like dimension.',
          'Curvature: $R^\\rho{}_{\\sigma\\mu\\nu}=\\partial_\\mu\\Gamma^\\rho{}_{\\nu\\sigma}-\\partial_\\nu\\Gamma^\\rho{}_{\\mu\\sigma}+\\Gamma^\\rho{}_{\\mu\\lambda}\\Gamma^\\lambda{}_{\\nu\\sigma}'
          '-\\Gamma^\\rho{}_{\\nu\\lambda}\\Gamma^\\lambda{}_{\\mu\\sigma}$, $R_{\\sigma\\nu}=R^\\rho{}_{\\sigma\\rho\\nu}$, $R=g^{\\sigma\\nu}R_{\\sigma\\nu}$, '
          '$G^A{}_B=R^A{}_B-\\frac12\\delta^A_BR$. In this signature a round sphere in the space-like block has NEGATIVE $R$ (for example $R=-12/r_0^2$ '
          'for the 4-sphere of radius $r_0$); the sign of $R$ flips with the sign of the metric.',
          'Field equations and action: $G^A{}_B-\\Lambda\\,\\delta^A_B=\\kappa\\,T^A{}_B$, $\\kappa=8\\pi G_8=M_8^{-6}$, from'])
    d.eq(r'S=-\frac1{2\kappa}\int d^8X\sqrt{|G|}\,\big(R+2\Lambda\big)-\int d^8X\sqrt{|G|}\,U+S_{\rm brane}+S_{\rm matter},')
    d.p('where $\\Lambda$ is the bulk cosmological constant ($\\Lambda>0$: de Sitter), $U$ the stabilizing energy density of the bulk (section 6), '
        '$S_{\\rm brane}$ the action of the world brane (section 7). Units $\\hbar=c=1$; $M_{\\rm Pl}=2.435\\times10^{18}$ GeV is the reduced Planck mass, '
        '$8\\pi G_4=M_{\\rm Pl}^{-2}$; the examples use $M_8=10$ TeV and $V_\\perp=M_{\\rm Pl}^2/M_8^6$ (the volume of the extra space today, section 4.4).')
    d.p('**The author’s note.** The note checked here is an e-mail of 28 October 2026 in which the author collected a discussion of the radion: '
        'the Kaluza–Klein ansatz with the factors $e^{2\\alpha\\phi}$, $e^{2\\beta\\phi}$, the Einstein frame and the canonical normalization, the '
        'physical volume, the radion as a modulus and the fifth force, stabilization (Goldberger–Wise), the warped alternative of Randall and '
        'Sundrum (RS1) with its junction conditions, normalization and mass, the mixing of the radion with the Higgs boson, and its effects on '
        'Higgs decays. The note uses the signature $(-,+,+,+)$, in which the scalar curvature has the opposite sign; its statements are '
        'translated into the conventions above. Section 11 lists every statement with the verdict of the checks.')

    # ==============================================================================================
    d.h1('3. The idea: a breathing extra space')
    d.p('Imagine at every point of ordinary space a tiny four-dimensional space, too small to see. If it were rigid, physics in ordinary space '
        'would never notice its size, only its effects on the constants of nature (for example $G_4=G_8/V$). If it can change size — bigger here, '
        'smaller there, oscillating in time — the size becomes a FIELD in ordinary spacetime. A field that changes from point to point carries '
        'kinetic energy, $\\frac12(\\partial\\phi)^2$, so it behaves like a particle: the radion. Two questions then decide everything: how is the '
        'size defined so that its kinetic energy has the standard form, and what energy does the extra space store as a function of its size '
        '(the potential, whose curvature is the mass of the radion)?')
    d.p('Two extra spaces are used as examples throughout:')
    d.ol(['**The 4-torus $T^4$** (the space of 7+1.nb): $x_4,\\dots,x_7$ periodic with period $L_c$, the flat metric $b^2\\delta_{ij}$, size $b$, proper '
          'volume $V=b^4L_c^4$. It is flat, so its size costs no curvature energy.',
          '**The 4-sphere $S^4$** (for comparison): $x_4,x_5,x_6\\in[0,\\pi]$, $x_7\\in[0,2\\pi)$ angles, radius $r$, the metric $r^2\\hat\\gamma$ with '
          '$\\hat\\gamma=\\mathrm{diag}(1,\\sin^2x_4,\\sin^2x_4\\sin^2x_5,\\sin^2x_4\\sin^2x_5\\sin^2x_6)$, proper volume $V=\\frac{8\\pi^2}3r^4$. It is curved, so '
          'its size costs energy — a sphere cannot be a modulus.'])

    # ==============================================================================================
    d.h1('4. The definition')
    d.h2('4.1 The metric ansatz')
    d.p('The RADION $\\beta(x)$ is defined by the eight-dimensional metric')
    d.eq(r'ds^2=e^{-4\beta(x)}\,g_{E\mu\nu}(x)\,dx^\mu dx^\nu-e^{2\beta(x)}\,\gamma_{ij}(y)\,dy^idy^j,')
    d.p('with a FIXED reference metric $\\gamma$ of the extra space — $\\gamma=b_0^2\\delta_{ij}$ on $T^4$, $\\gamma=r_0^2\\hat\\gamma$ on $S^4$ — and the '
        'four-dimensional EINSTEIN-FRAME metric $g_E$. The size is $b=b_0e^\\beta$ on $T^4$ and the radius $r=r_0e^\\beta$ on $S^4$: $\\beta=\\ln(b/b_0)$, '
        'the same field as in section 20.3 of 7+1.nb. In the notation of the note, $ds^2=e^{2\\alpha\\phi}g+e^{2\\beta\\phi}\\gamma$ (signature $(-,+,+,+)$) with '
        'constants $\\alpha,\\beta$ and a field $\\phi$: our $\\beta(x)$ is the note’s $\\beta\\phi(x)$ and our $-2\\beta(x)$ its $\\alpha\\phi(x)$.')
    d.h2('4.2 Why the factor $e^{-4\\beta}$: the Einstein frame')
    d.p('Under a constant rescaling $g\\to\\Omega^2g$ the scalar curvature scales as $R\\to\\Omega^{-2}R$ and the volume element as '
        '$\\sqrt{|g|}\\to\\Omega^4\\sqrt{|g|}$ (four dimensions). For the 4D block $e^{2\\alpha}g$ and the internal block $e^{2\\beta}\\gamma$ ($n$ extra dimensions) '
        'the eight-dimensional volume element and the 4D part of the curvature give')
    d.eq(r'\sqrt{|G|}\,R[G]\supset e^{4\alpha}e^{n\beta}\sqrt{|g|}\sqrt\gamma\cdot e^{-2\alpha}R[g]=e^{2\alpha+n\beta}\sqrt{|g|}\sqrt\gamma\,R[g] .')
    d.p('The coefficient of $\\sqrt{|g|}R[g]$ — the strength of four-dimensional gravity — is constant if and only if')
    d.eq(r'2\alpha+n\beta=0:\qquad n=4:\ \alpha=-2\beta .')
    d.p('This is the Einstein frame. If the factor were absent ($\\alpha=0$), Newton’s constant would be $G_4=G_8/V_0e^{4\\beta}$, a field — the '
        'description known as the Jordan frame; both describe the same physics, but only in the Einstein frame is the graviton cleanly separated '
        'from the radion.')
    d.h2('4.3 The reduced action and the canonical radion')
    d.p('Insert the ansatz into the action of section 2 and integrate over the extra space ($\\int d^4y\\sqrt\\gamma=V_0$). Section 26.1 of 7+1.nb '
        'proves, for the homogeneous metrics $g_E=\\mathrm{diag}(N^2,-a^2,-a^2,-a^2)$ with arbitrary $N(x_0)$, $a(x_0)$, $\\beta(x_0)$ (the Euler–Lagrange '
        'expressions of the difference of the two sides vanish identically, so the difference is a total derivative), that')
    d.eq(r'-\frac1{2\kappa}\int d^4y\sqrt{|G|}\,(R+2\Lambda)-\int d^4y\sqrt{|G|}\,U=\sqrt{|g_E|}\,\Big[-\frac{M_{\rm Pl}^2}2R_E+6M_{\rm Pl}^2\,g_E^{\mu\nu}\partial_\mu\beta\,\partial_\nu\beta-V(\beta)\Big]+\text{(total derivative)},')
    d.eq(r'M_{\rm Pl}^2=\frac{V_0}\kappa,\qquad V(\beta)=e^{-4\beta}\Big[M_{\rm Pl}^2\Lambda+V_0U-\frac{M_{\rm Pl}^2}2R_{\rm int}\Big],\qquad R_{\rm int}=\begin{cases}0&(T^4)\\[2pt] \dfrac{12}{r_0^2e^{2\beta}}=\dfrac{12}{r^2}&(S^4)\end{cases}')
    d.p('($R_{\\rm int}$ is the scalar curvature of the extra space itself, positive for the sphere; $R_E$ that of $g_E$ in the signature of section 2). '
        'The kinetic term $6M_{\\rm Pl}^2(\\partial\\beta)^2$ is that of a canonically normalized scalar,')
    d.eq(r'6M_{\rm Pl}^2(\partial\beta)^2=\frac12(\partial\phi)^2\iff \phi=\sqrt{12}\,M_{\rm Pl}\,\beta=\sqrt{12}\,M_{\rm Pl}\ln\frac b{b_0},')
    d.p('the CANONICAL RADION. Its mass is the curvature of the potential at the minimum, $m_r^2=d^2V/d\\phi^2=V\'\'(\\beta)/(12M_{\\rm Pl}^2)$.')
    d.h3('Worked example 1 (the torus): the reduction step by step')
    d.p('On $T^4$ the internal metric $e^{2\\beta}b_0^2\\delta_{ij}$ is flat, so $R_{\\rm int}=0$, and $\\sqrt{|G|}=e^{-8\\beta}e^{4\\beta}\\sqrt{|g_E|}b_0^4=e^{-4\\beta}\\sqrt{|g_E|}b_0^4$. '
        'The eight-dimensional curvature of the ansatz contains $e^{4\\beta}R_E$ (from the 4D block) plus terms with $\\partial\\beta$; after the '
        'integration over $T^4$ ($V_0=b_0^4L_c^4$) and integrations by parts only $6M_{\\rm Pl}^2(\\partial\\beta)^2$ survives, and the potential is '
        '$V=e^{-4\\beta}(M_{\\rm Pl}^2\\Lambda+V_0U)$. With $\\Lambda=U=0$ the torus is a modulus: any constant $\\beta$ is a solution.')
    d.h3('Worked example 2 (the sphere): the extra potential')
    d.p('On $S^4$ the internal metric $e^{2\\beta}r_0^2\\hat\\gamma$ has $R_{ij}=3\\hat\\gamma_{ij}$ and $R_{\\rm int}=12/(r_0^2e^{2\\beta})$ (section 5.2). The '
        'term $-\\frac1{2\\kappa}\\sqrt{|G|}R$ contributes $+\\frac{V_0}{2\\kappa}e^{-4\\beta}R_{\\rm int}$ to the Lagrangian, i.e. the potential')
    d.eq(r'V_{\rm curv}(\beta)=-\frac{M_{\rm Pl}^2}2e^{-4\beta}\frac{12}{r_0^2e^{2\beta}}=-\frac{6M_{\rm Pl}^2}{r_0^2}\,e^{-6\beta}:')
    d.p('negative and growing without bound as the sphere shrinks ($\\beta\\to-\\infty$). Without anything else the sphere collapses; its size must be held '
        '(section 6).')
    d.h2('4.4 The physical volume and the size')
    d.p('The proper volume of the extra space at the point $x$ is')
    d.eq(r'V(x)=\int d^4y\,\sqrt{\det\big(e^{2\beta(x)}\gamma_{ij}\big)}=V_0\,e^{4\beta(x)}=V_0\exp\Big(\frac{2\,\phi(x)}{\sqrt3\,M_{\rm Pl}}\Big),\qquad V_0=\begin{cases}b_0^4L_c^4&(T^4)\\ \frac{8\pi^2}3r_0^4&(S^4)\end{cases}')
    d.p('Measuring $V$ measures the radion. Today, with $M_8=10$ TeV, the volume is fixed by Newton’s constant: $V_\\perp=M_{\\rm Pl}^2/M_8^6=%s$ GeV$^{-4}$, the '
        'torus has the proper size $\\ell_\\perp=V_\\perp^{1/4}=%s$ GeV$^{-1}$ $=%s$ m, and a sphere of the same volume has the radius '
        '$r_{S^4}=(3V_\\perp/(8\\pi^2))^{1/4}=%s$ GeV$^{-1}$ $=%s$ m.' % (g(ttb, 0, 4), g(ttb, 1, 5), g(ttb, 2, 4), v('today', 0, 5), v('today', 1, 5)))
    d.h2('4.5 $n$ extra dimensions, and the factor of the note')
    d.p('For a torus $T^n$ ($D=4+n$) with the Einstein-frame factor $e^{-n\\beta}$ in front of $g_E$, section 26.1 SOLVES the reduction for the '
        'coefficient of the kinetic term: with $\\beta=\\phi$,')
    d.align([r'-\frac1{2\kappa}\int d^ny\sqrt{|G|}\,R&=\sqrt{|g_E|}\,\Big[-\frac{M_{\rm Pl}^2}2R_E+\frac{M_{\rm Pl}^2}2\,c_n\,(\partial\beta)^2\Big]+\text{(total derivative)},',
             r'c_n&=\frac{n(n+2)}2:\qquad c_1=%s,\quad c_2=%s,\quad c_3=%s,\quad c_4=%s .' % (v('kin', 0, 3), v('kin', 1, 3), v('kin', 2, 3), v('kin', 3, 3))])
    d.p('With $\\beta=\\beta_n\\varphi$ the kinetic term is $\\frac{M_{\\rm Pl}^2}2c_n\\beta_n^2(\\partial\\varphi)^2$. The note chooses')
    d.eq(r'\alpha=-\sqrt{\frac n{2(n+2)}},\qquad \beta_n=\sqrt{\frac2{n(n+2)}}\qquad(2\alpha+n\beta_n=0\ \checkmark),')
    d.p('and states the reduced action $\\frac{V_n}{2\\kappa^2}\\int\\sqrt{-g}\\,[R-\\frac12(\\partial\\varphi)^2]$ (signature $(-,+,+,+)$). The check gives '
        '$c_n\\beta_n^2=1$ for the note’s $\\beta_n$ ($\\beta_4^2=%s$): the reduced action is $\\frac{V_n}{2\\kappa^2}\\int\\sqrt{-g}\\,[R-(\\partial\\varphi)^2]$ — '
        '**a factor 2 in the kinetic term**. The form with $\\frac12$ needs $c_n\\beta_n^2=\\frac12$:' % v('beta2', 0, 4))
    d.eq(r'\beta_n=\frac1{\sqrt{n(n+2)}},\qquad \alpha=-\frac n2\beta_n=-\sqrt{\frac n{4(n+2)}}\qquad(n=4:\ \beta_4^2=%s).' % v('beta2', 1, 4))
    d.p('For the eight-dimensional case the note uses $\\alpha=-1/\\sqrt3$, $\\beta=1/\\sqrt{12}$ with the action $\\int\\sqrt{-g}[\\frac{M_{\\rm Pl}^2}2R-\\frac12(\\partial\\phi)^2]$. '
        'This is right if the exponent is read as $\\beta\\phi/M_{\\rm Pl}$: then $\\beta(x)_{\\rm here}=\\phi/(\\sqrt{12}M_{\\rm Pl})$, exactly the canonical radion '
        'of section 4.3, and $V=V_0e^{4\\beta\\phi/M_{\\rm Pl}}=V_0e^{(2/\\sqrt3)\\phi/M_{\\rm Pl}}$ as the note says.')
    d.h3('Worked example 3: one extra dimension ($n=1$), the classic Kaluza–Klein scalar')
    d.p('For $n=1$: $c_1=\\frac32$, so the canonical choice is $\\beta_1^2=\\frac13$, $\\alpha^2=\\frac1{12}$ — the textbook values of five-dimensional '
        'Kaluza–Klein theory ($ds^2=e^{2\\alpha\\varphi}g+e^{2\\beta\\varphi}dz^2$ with $\\beta=-2\\alpha$, $\\alpha^2=\\frac1{12}$). The note’s formula would give '
        '$\\beta_1^2=\\frac23$, twice the textbook value.')

    # ==============================================================================================
    d.h1('5. The two extra spaces')
    d.h2('5.1 The 4-torus')
    d.p('$T^4=\\mathbb R^4/(L_c\\mathbb Z)^4$ with the metric $b^2\\delta_{ij}$: flat ($R_{ijkl}=0$), volume $b^4L_c^4$, isometries the four translations and '
        'the 384 signed permutations of the axes. Only the product $bL_c$ is physical. The torus is the auxiliary space of 7+1.nb.')
    d.h2('5.2 The 4-sphere')
    d.p('The unit 4-sphere is the set of points of $\\mathbb R^5$ at distance 1 from the origin, with the coordinates')
    d.eq(r'(X_1,\dots,X_5)=r\big(\sin x_4\sin x_5\sin x_6\cos x_7,\ \sin x_4\sin x_5\sin x_6\sin x_7,\ \sin x_4\sin x_5\cos x_6,\ \sin x_4\cos x_5,\ \cos x_4\big);')
    d.p('the embedding induces the metric $r^2\\hat\\gamma$, $\\hat\\gamma=\\mathrm{diag}(1,\\sin^2x_4,\\sin^2x_4\\sin^2x_5,\\sin^2x_4\\sin^2x_5\\sin^2x_6)$, and')
    d.eq(r'R_{ij}=3\,\hat\gamma_{ij},\qquad R_{\rm int}=\frac{12}{r^2},\qquad V=r^4\int_0^\pi\!\!\int_0^\pi\!\!\int_0^\pi\!\!\int_0^{2\pi}\sin^3x_4\sin^2x_5\sin x_6\,dx_4dx_5dx_6dx_7=\frac{8\pi^2}3r^4,')
    d.p('all checked in section 26.1 (in the signature of 7+1.nb the space-like block $-r^2\\hat\\gamma$ has $R=-12/r^2$). Its isometries are the 10 '
        'rotations of $\\mathbb R^5$, the group $SO(5)$; the north pole is $x_4=0$, the point $(0,0,0,0,r)$.')
    d.h2('5.3 Side by side')
    d.table(['', '$T^4$', '$S^4$'], [
        ['reference metric $\\gamma$', '$b_0^2\\delta_{ij}$', '$r_0^2\\hat\\gamma$'],
        ['size', '$b=b_0e^\\beta$', '$r=r_0e^\\beta$'],
        ['volume $V_0e^{4\\beta}$', '$V_0=b_0^4L_c^4$', '$V_0=\\frac{8\\pi^2}3r_0^4$'],
        ['internal curvature $R_{\\rm int}$', '$0$', '$12/r^2$'],
        ['curvature potential', 'none', '$-6M_{\\rm Pl}^2e^{-6\\beta}/r_0^2$'],
        ['isometries', '$U(1)^4$ translations, 384 signed permutations', '$SO(5)$ (10 rotations)'],
        ['radius today ($V=V_\\perp$)', '$\\ell_\\perp=%s$ m' % g(ttb, 2, 4), '$r_{S^4}=%s$ m' % v('today', 1, 4)],
        ['lowest Kaluza–Klein mass (scalar)', '$2\\pi/\\ell_\\perp=%s$ MeV' % v('today', 2, 5), '$2/r_{S^4}=%s$ MeV' % v('today', 3, 5)],
        ['Dirac zero modes', '4 (constant spinors)', 'none (lowest $|\\lambda|=2/r$)'],
    ], widths=[0.3, 0.35, 0.35])

    # ==============================================================================================
    d.h1('6. The potential and the mass of the radion')
    d.h2('6.1 How each energy scales with the size')
    d.p('In the Einstein frame every energy of the bulk carries the factor $\\sqrt{|G|}=e^{-4\\beta}\\sqrt{|g_E|}\\sqrt\\gamma$ and, if it contains derivatives along '
        'the extra space or its curvature, factors $e^{-2\\beta}$ from $G^{ij}=-e^{-2\\beta}\\gamma^{ij}$:')
    d.table(['energy in the bulk', 'Einstein-frame potential', 'scaling'], [
        ['bulk cosmological constant $\\Lambda$', '$M_{\\rm Pl}^2\\Lambda e^{-4\\beta}$', '$e^{-4\\beta}$'],
        ['stabilizing energy density $U(\\beta)$', '$V_0U\\,e^{-4\\beta}$', '$e^{-4\\beta}$'],
        ['curvature of $S^4$', '$-6M_{\\rm Pl}^2e^{-6\\beta}/r_0^2$', '$e^{-6\\beta}$'],
        ['gradient energy of a field along $y$', '$\\frac12\\int\\sqrt\\gamma\\,|\\nabla\\Phi|_\\gamma^2\\,e^{-6\\beta}$', '$e^{-6\\beta}$'],
        ['mass energy of that field', '$\\frac12\\int\\sqrt\\gamma\\,m^2\\Phi^2\\,e^{-4\\beta}$', '$e^{-4\\beta}$'],
        ['magnetic 4-form flux through $S^4$ (illustration)', '$M_{\\rm Pl}^2\\kappa\\rho_F^{(0)}e^{-12\\beta}$', '$e^{-12\\beta}$'],
    ], widths=[0.4, 0.4, 0.2])
    d.p('With the stabilizing energy density of section 20.3, written around the minimum,')
    d.eq(r'U(\beta)=U_0+U_1\beta+\frac{K_U}2\beta^2,\qquad V(\beta)=M_{\rm Pl}^2\Big[e^{-4\beta}\big(\Lambda+\kappa U(\beta)\big)-\frac{6\,\sigma}{r_0^2}e^{-6\beta}+F\,e^{-12\beta}\Big]')
    d.p('($\\sigma=0$ for $T^4$, $\\sigma=1$ for $S^4$; $F=\\kappa\\rho_F^{(0)}$ the flux term, zero unless stated). A static FLAT four-dimensional vacuum at '
        '$\\beta=0$ needs $V(0)=0$ (no four-dimensional cosmological constant) and $V\'(0)=0$ (a stationary point); it is stable if $V\'\'(0)>0$, and '
        'then $m_r^2=V\'\'(0)/(12M_{\\rm Pl}^2)$. Each case below is checked in section 26.2 in two independent ways — from $V(\\beta)$ and from the '
        'eight-dimensional field equations (section 6.7).')
    d.h2('6.2 Without stabilization: a modulus, and the fifth force')
    d.p('On $T^4$ with $\\Lambda=U=0$, $V\\equiv0$: the radion is a MODULUS, a massless field whose value is not fixed. A massless radion couples to '
        'every mass on the brane (section 7.1) and mediates a long-range force of $\\frac23$ the strength of gravity — excluded by tests of gravity. '
        'With $\\Lambda\\ne0$ and $U=0$, $V=M_{\\rm Pl}^2\\Lambda e^{-4\\beta}$ has no minimum: the torus runs away. On $S^4$ the curvature term alone '
        'drives the sphere to collapse. A realistic model therefore needs a STABILIZER.')
    d.h2('6.3 Example 1: the torus with $U$')
    d.eq(r"V(0)=M_{\rm Pl}^2(\Lambda+\kappa U_0)=0,\qquad V'(0)=M_{\rm Pl}^2\big(-4(\Lambda+\kappa U_0)+\kappa U_1\big)=0,\qquad V''(0)=M_{\rm Pl}^2\kappa K_U,")
    d.eq(r'\Lambda+\kappa U_0=0,\qquad U_1=0,\qquad m_r^2=\frac{\kappa K_U}{12}\quad\text{(as in section 20.3 of 7+1.nb).}')
    d.h2('6.4 Example 2: the sphere with $U$')
    d.p('The curvature must be balanced:')
    d.align([r"V(0)&=M_{\rm Pl}^2\Big(\Lambda+\kappa U_0-\frac6{r_0^2}\Big)=0,\qquad V'(0)=M_{\rm Pl}^2\Big(-4(\Lambda+\kappa U_0)+\kappa U_1+\frac{36}{r_0^2}\Big)=0,",
             r"V''(0)&=M_{\rm Pl}^2\Big(16(\Lambda+\kappa U_0)-8\kappa U_1+\kappa K_U-\frac{216}{r_0^2}\Big),"])
    d.eq(r'(\Lambda+\kappa U_0)\,r_0^2=%s,\qquad \kappa U_1\,r_0^2=%s,\qquad m_r^2=\frac{\kappa K_U}{12}%s\,\frac1{r_0^2}.'
         % (iv('sphU', 0), iv('sphU', 1), iv('sphU', 2)))
    d.p('A sphere needs a stiffer stabilizer than a torus: its curvature lowers the mass by $2/r_0^2$. With $r_0=r_{S^4}$ today, $2/r_0^2$ corresponds '
        'to a mass of $\\sqrt2/r_{S^4}=%s$ MeV — negligible against a radion mass of 10 GeV.' % (fmt(R.nbv(D, 'today')[3]/2**0.5, 4) if R.nbv(D, 'today') else '?'))
    d.h2('6.5 Example 3: the sphere held by $\\Lambda$ alone — unstable')
    d.p('With $U=0$, $V=M_{\\rm Pl}^2(\\Lambda e^{-4\\beta}-6e^{-6\\beta}/r_0^2)$ has a stationary point at $V\'(0)=0$, i.e. $\\Lambda r_0^2=%s$, where '
        '$V(0)=3M_{\\rm Pl}^2/r_0^2>0$: four-dimensional de Sitter space with $H^2=V(0)/(3M_{\\rm Pl}^2)$, $H^2r_0^2=%s$ — the eight-dimensional solution '
        '$dS_4\\times S^4$, which section 26.2 also verifies in the eight-dimensional field equations. But $V\'\'(0)=-72M_{\\rm Pl}^2/r_0^2$:'
        % (iv('sphL', 0), iv('sphL', 1)))
    d.eq(r"m^2=\frac{V''(0)}{12M_{\rm Pl}^2}=-\frac6{r_0^2}=%s\,H^2<0 ." % iv('sphL', 2))
    d.p('The radion sits at a MAXIMUM (a tachyon): a sphere held only by a positive cosmological constant either collapses or decompactifies.')
    d.h2('6.6 Example 4: the sphere held by a flux (illustration)')
    d.p('7+1.nb has no 4-form field, but the classic way to hold a sphere is a magnetic 4-form flux through it (Freund–Rubin): its energy density is '
        '$\\rho_F=q^2/(2b^8)$ for the sphere of radius $b$, with the pressures $p_a=-\\rho_F$ along ordinary space and $p_b=+\\rho_F$ along the sphere '
        '(from its comoving energy $W=a^3b^4q^2/(2b^8)$, as in section 20 of 7+1.nb), and in the Einstein frame it scales as $e^{-12\\beta}$. A '
        'Minkowski vacuum then exists and is stable:')
    d.eq(r"V(0)=0,\ V'(0)=0:\qquad \Lambda r_0^2=%s,\qquad \kappa\rho_Fr_0^2=%s,\qquad m^2r_0^2=%s .  " % (v('sphF', 0, 3), v('sphF', 1, 3), iv('sphF', 2)))
    d.h2('6.7 The same results from the eight-dimensional field equations')
    d.p('For the cosmological metric $ds^2=dx_0^2-a^2d\\vec x^2-b^2d\\Omega_4^2$ (the sphere of radius $b(x_0)$) the Einstein tensor differs from that '
        'of the torus ($ds^2=dx_0^2-a^2d\\vec x^2-b^2d\\vec y^2$) by')
    d.eq(r'G^A{}_A\big|_{S^4}-G^A{}_A\big|_{T^4}=\frac{(6,6,6,6,3,3,3,3)}{b^2},\qquad R\big|_{S^4}-R\big|_{T^4}=-\frac{12}{b^2},')
    d.p('and the radion equation of section 20.3 (Einstein gravity, from the $11$ and $44$ field equations with the $00$ constraint; $H_a=a\'/a$, '
        '$H_b=b\'/b=\\beta\'$; $\\varepsilon$, $p_a$, $p_b$ the energy density and pressures of the bulk matter) becomes')
    d.eq(r"\beta''+3H_a\beta'+4\beta'^2=\kappa\Big(\frac\varepsilon6-\frac{p_a}2+\frac{p_b}3\Big)+\frac\Lambda3-\frac{3\sigma}{b^2}\qquad(\sigma=0:\ T^4,\ \sigma=1:\ S^4).")
    d.p('The stabilizer contributes $\\varepsilon=U$, $p_a=-U$, $p_b=-U-\\frac b4U\'(b)$; the static solutions and the linearized restoring terms of this '
        'equation reproduce every result of sections 6.3–6.6 (section 26.2).')
    d.h2('6.8 A bulk field as the stabilizer: the Einstein-frame factor')
    d.p('The note stabilizes the radion with a bulk scalar $\\Phi(y)$ of mass $m_8$ (Goldberger and Wise) and writes its energy, with the note’s $\\beta$, as '
        '$V(\\phi)=\\int d^4y\\sqrt\\gamma\\,e^{4\\beta\\phi}[\\frac12e^{-2\\beta\\phi}(\\nabla\\Phi)^2+\\frac12m_8^2\\Phi^2]$. The factor $e^{4\\beta\\phi}$ is the internal volume '
        'element only; the four-dimensional block contributes $e^{4\\alpha\\phi}=e^{-8\\beta\\phi}$. Section 26.2 checks, for a static profile $\\Phi(x_4,x_5)$ '
        'on $S^4$,')
    d.eq(r'\sqrt{|G|}\Big(\frac12G^{AB}\partial_A\Phi\partial_B\Phi-\frac12m_8^2\Phi^2\Big)=-\sqrt{|g_E|}\sqrt\gamma\,e^{-4\beta}\Big(\frac12e^{-2\beta}|\nabla\Phi|^2_\gamma+\frac12m_8^2\Phi^2\Big),')
    d.p('so the Einstein-frame potential is $e^{-4\\beta}\\int\\sqrt\\gamma\\,[\\frac12e^{-2\\beta}|\\nabla\\Phi|^2+\\frac12m_8^2\\Phi^2]$: the gradient energy scales as '
        '$e^{-6\\beta}$, like the curvature of the sphere, the mass energy as $e^{-4\\beta}$, like $U$ — not as $e^{+2\\beta}$ and $e^{+4\\beta}$. Its minimum, '
        'where the two compete, fixes the size. (On $T^4$ a non-constant $\\Phi$ needs sources, for example boundary values on branes; the note’s '
        'boundary values $v_A$, $v_B$ play this role in the warped case of section 9.)')

    # ==============================================================================================
    d.h1('7. The radion and the world brane')
    d.h2('7.1 The coupling: the same on $T^4$ and $S^4$')
    d.p('The world brane is the 3+1-dimensional surface $y=0$ (on $T^4$) or the north pole $x_4=0$ (on $S^4$). Brane fields feel the INDUCED metric, the '
        '4D block of the ansatz at that point:')
    d.eq(r'h_{\mu\nu}(x)=e^{-4\beta(x)}\,g_{E\mu\nu}(x)\qquad\text{(on both spaces: the factor depends only on }n=4\text{).}')
    d.p('A particle of mass $M$ at rest on the brane has the action $-M\\int d\\tau=-M\\int dx_0\\,e^{-2\\beta}=-M\\int dx_0\\,(1-2\\beta+\\dots)$, so with '
        '$\\beta=\\phi/(\\sqrt{12}M_{\\rm Pl})$:')
    d.eq(r'\mathcal L_{\rm int}=\frac{\phi}{\sqrt3\,M_{\rm Pl}}\,T^\mu{}_\mu\qquad(T^\mu{}_\mu=M\ \text{for the particle}),')
    d.p('the coupling of section 20.3 of 7+1.nb. For $n$ extra dimensions $h=e^{-n\\beta}g_E$ and the canonical $\\beta=\\phi/(M_{\\rm Pl}\\sqrt{n(n+2)/2})$ give '
        'the coupling $\\sqrt{n/(2(n+2))}/M_{\\rm Pl}$ (section 26.3).')
    d.h2('7.2 The fifth force and the Eöt-Wash bound')
    d.p('A scalar coupled with $g\\,\\phi M$ to two masses adds the potential $-g^2MM\'e^{-m_rr}/(4\\pi r)=-\\alpha\\,G_4MM\'e^{-m_rr}/r$ with $\\alpha=2(gM_{\\rm Pl})^2$. '
        'For the radion $g=1/(\\sqrt3M_{\\rm Pl})$:')
    d.eq(r'\alpha=2\Big(\frac{M_{\rm Pl}}{\sqrt3M_{\rm Pl}}\Big)^2=\frac23,\qquad\text{in general}\quad \alpha=\frac n{n+2} .')
    d.p('Without a mass the long-range force would be $(1+\\frac23)G_4MM\'/r=\\frac53G_4MM\'/r$ — the factor $\\frac53$ that the sum over the images of a '
        'mass on the torus produces (section 25.4 of 7+1.nb). The Eöt-Wash torsion balance (Lee et al. 2020) excludes Yukawa forces of '
        'gravitational strength ($|\\alpha|=1$) with a range $\\lambda>38.6\\,\\mu$m; a radion of strength $\\frac23$ must therefore be heavier than about')
    d.eq(r'm_r\gtrsim\frac{\hbar c}{38.6\,\mu{\rm m}}=%s\ {\rm eV}.' % v('ew', 0, 4))
    d.p('The radion of 7+1.nb (sections 22–24) has $m_r=10$ GeV and the range $\\hbar c/(10\\,{\\rm GeV})=%s$ m: far below any test of gravity.' % v('ew', 1, 4))
    d.h2('7.3 The radion and the Higgs boson: mixing')
    d.p('The Higgs doublet $H$ lives on the brane ($H^\\dagger H=\\varphi_H^2/2$ in unitary gauge, $\\varphi_H=v+h$, $v=246$ GeV). Besides its kinetic term '
        'and potential it may couple to the curvature of the induced metric (Giudice, Rattazzi and Wells); written in the signature of 7+1.nb, where '
        'the note’s $-\\xi\\int\\sqrt{-g}R\\,H^\\dagger H$ changes the sign of $R$,')
    d.eq(r'\mathcal L=\sqrt{|h|}\Big[\frac12h^{\mu\nu}\partial_\mu\varphi_H\partial_\nu\varphi_H-\frac\lambda4\big(\varphi_H^2-v^2\big)^2+\frac\xi2R(h)\,\varphi_H^2\Big]+\frac12(\partial r)^2-\frac12m_{r0}^2r^2 \qquad(\xi=\tfrac16:\ \text{conformal}).')
    d.p('Here $h=\\Omega^2\\eta$ with $\\Omega=1+r/\\Lambda_r+O(r^2)$, $r$ the canonically normalized radion and $\\Lambda_r$ its coupling scale: in 7+1 '
        '$\\Omega=e^{-2\\beta}=e^{-\\phi/(\\sqrt3M_{\\rm Pl})}$, $\\Lambda_r=-\\sqrt3M_{\\rm Pl}$ (the sign can be absorbed into $r\\to-r$); in Randall–Sundrum '
        '$\\Lambda_r=\\langle\\mu\\rangle$ (section 9). Define $\\gamma=v/\\Lambda_r$. Section 26.6 proves:')
    d.ol(['For $h=\\Omega^2\\eta$ in four dimensions, $\\sqrt{|h|}R(h)=c\\,\\Omega\\,\\Box\\Omega$ with $c=%s$, $\\Box=\\partial_0^2-\\nabla^2$.' % iv('hrk', 0),
          'Expanded to second order in $(h,r)$ and up to total derivatives (the terms linear in the fields are total derivatives — the vacuum is a solution):'])
    d.eq(r'\mathcal L^{(2)}=\frac12(\partial h)^2+\frac12\big(1+6\xi\gamma^2\big)(\partial r)^2+6\xi\gamma\,\partial h\cdot\partial r-\frac12m_{h0}^2h^2-\frac12m_{r0}^2r^2,\qquad m_{h0}^2=2\lambda v^2 .')
    d.p('(The coefficients $K_{hr}/(\\xi\\gamma)=%s$ and $(K_{rr}-1)/(\\xi\\gamma^2)=%s$ are read off the Euler–Lagrange equations of the expanded Lagrangian.) '
        'The note writes the kinetic terms without the $6\\xi\\gamma^2$ of the radion, but its normalization factor contains it:' % (iv('hrk', 1), iv('hrk', 2)))
    d.align([r"h&=h'-\frac{6\xi\gamma}Z\,r',\qquad r=\frac{r'}Z:\qquad \text{canonical}\iff Z^2=1+6\xi\gamma^2(1-6\xi)",
             r"&\qquad(\text{with the note's literal kinetic terms: }Z^2=1-36\xi^2\gamma^2)."])
    d.p('The mass matrix of $(h\',r\')$ is $M\'=\\begin{pmatrix}m_{h0}^2&-6\\xi\\gamma m_{h0}^2/Z\\\\-6\\xi\\gamma m_{h0}^2/Z&(m_{r0}^2+36\\xi^2\\gamma^2m_{h0}^2)/Z^2\\end{pmatrix}$. '
        'With $h\'=\\cos\\theta\\,h_m-\\sin\\theta\\,r_m$, $r\'=\\sin\\theta\\,h_m+\\cos\\theta\\,r_m$ its off-diagonal element becomes '
        '$-\\frac12(M\'_{11}-M\'_{22})\\sin2\\theta+M\'_{12}\\cos2\\theta$, which vanishes for')
    d.align([r"\tan2\theta&=\frac{2M'_{12}}{M'_{11}-M'_{22}}=\frac{12\gamma\xi Z\,m_{h0}^2}{m_{r0}^2-m_{h0}^2\big(Z^2-36\xi^2\gamma^2\big)},",
             r"h&=C_h\,h_m+\dots,\quad r=C_r\,h_m+\dots,\qquad C_h=\cos\theta-\frac{6\xi\gamma}Z\sin\theta,\quad C_r=\frac{\sin\theta}Z,"])
    d.p('the formulas of the note. (The note displays the rotation matrix with the primed and unprimed fields interchanged; with that reading the '
        'off-diagonal element is $+\\frac12(M\'_{11}-M\'_{22})\\sin2\\theta+M\'_{12}\\cos2\\theta$ and $\\theta$ would change sign.) The physical Higgs $h_m$ '
        'couples to Standard Model fields through $h$ (factor $C_h$) and, through its radion part (factor $C_r$), to the trace of their energy–momentum '
        'tensor, including the trace anomaly; the note writes, with its values $b_{\\rm EM}=-\\frac{11}3$, $F_{\\rm SM}=-6.5$, $b_{\\rm QCD}=7$, $F_{\\rm heavy}=-\\frac43$,')
    d.eq(r'\frac{\Gamma(h\to\gamma\gamma)}{\Gamma_{\rm SM}}=\Big|C_h+C_r\gamma\frac{b_{\rm EM}}{F_{\rm SM}}\Big|^2,\qquad \frac{\Gamma(h\to gg)}{\Gamma_{\rm SM}}=\Big|C_h+C_r\gamma\frac{b_{\rm QCD}}{F_{\rm heavy}}\Big|^2 .')
    d.h3('Worked example 4: the Higgs boson and the radion in 7+1 (on $T^4$ or $S^4$)')
    d.p('In 7+1, $\\gamma=v/(\\sqrt3M_{\\rm Pl})=%s$. For $\\xi=1$, $m_{r0}=10$ GeV, $m_{h0}=125.20$ GeV (60-digit arithmetic in both programs):'
        % v('ew', 2, 4))
    d.align([r'Z-1&=%s,\qquad \theta=%s,' % (fmt(R.nbv(D, 'hr71')[0], 4) if R.nbv(D, 'hr71') else '?', v('hr71', 1, 4)),
             r'\frac{\Gamma(h\to\gamma\gamma)}{\Gamma_{\rm SM}}-1&=%s,\qquad \frac{\Gamma(h\to gg)}{\Gamma_{\rm SM}}-1=%s .' % (v('hr71', 2, 4), v('hr71', 3, 4))])
    d.p('The flat radion of 7+1 cannot be seen through the Higgs boson. The bounds the note derives from LHC data ($\\langle\\mu\\rangle>2.5$–$3$ TeV, '
        '$-0.1<\\xi<0.4$) concern the warped radion, for which $\\gamma=v/(3\\,{\\rm TeV})=%s$ (the note’s 0.08) and the same formulas give large '
        'effects. They are quoted from the note; this document does not repeat the fit to the LHC data.' % v('hr71', 4, 3))

    # ==============================================================================================
    d.h1('8. Kaluza–Klein levels, the brane and dirac16complex on $T^4$ and $S^4$')
    d.h2('8.1 The levels of a scalar field')
    d.p('A bulk field $\\Psi(x,y)=\\sum_n\\psi_n(x)Y_n(y)$ with $-\\Delta_\\gamma Y_n=\\mu_n^2Y_n$ appears in ordinary spacetime as a tower of fields of mass $\\mu_n$:')
    d.table(['', '$T^4$ (period $\\ell_\\perp$)', '$S^4$ (radius $r$)'], [
        ['eigenfunctions', '$e^{2\\pi i\\vec n\\cdot\\vec y/\\ell_\\perp}/\\sqrt V$, $\\vec n\\in\\mathbb Z^4$', 'spherical harmonics of degree $l=0,1,2,\\dots$'],
        ['masses', '$\\mu=2\\pi|\\vec n|/\\ell_\\perp$', '$\\mu=\\sqrt{l(l+3)}/r$'],
        ['multiplicity', '$r_4(k)=8\\sigma(k)-32\\sigma(k/4)$ for $|\\vec n|^2=k$', '$d_l=\\frac{(2l+3)(l+1)(l+2)}6=\\binom{l+4}4-\\binom{l+2}4$'],
        ['first multiplicities', '$r_4(1..4)=8,24,32,24$', '$d_{0..8}=' + ','.join(iv('dl', i) for i in range(9)) + '$'],
        ['Weyl’s law', '$N(\\mu)\\approx V\\mu^4/(32\\pi^2)$', '$N(\\mu)\\approx V\\mu^4/(32\\pi^2)=(\\mu r)^4/12$'],
    ], widths=[0.2, 0.4, 0.4])
    d.p('On $S^4$ the number of states with $l(l+3)\\le x^2$ is exact: with $L$ the largest such $l$ and $y=L+2$, $N=\\sum_{l\\le L}d_l=y^2(y^2-1)/12$. For '
        'integer $x$ ($y=x$) the relative deviation from Weyl’s law is exactly $-1/x^2$: $%s$, $%s$, $%s$ at $x=\\mu r=10,100,1000$. Between integers '
        'the count jumps by $d_L\\approx L^3/3$ at each level, so the deviation oscillates with an amplitude of about $4/x$.'
        % (v('weyl', 0, 3), v('weyl', 1, 3), v('weyl', 2, 3)))
    d.h3('Worked example 5: the two spaces today')
    d.p('With the same volume $V_\\perp$ (the same Newton constant): torus $\\ell_\\perp=%s$ m, lowest mass $2\\pi/\\ell_\\perp=%s$ MeV; sphere $r_{S^4}=%s$ m, '
        'lowest mass $\\sqrt{1\\cdot4}/r=%s$ MeV. Below 5 GeV the torus has %s states (an exact lattice count), the sphere %s (exact), Weyl’s law '
        'predicts $%s$ for both — the two spaces cannot be told apart by counting heavy levels, only by the lowest ones.'
        % (g(ttb, 2, 4), v('today', 2, 5), v('today', 1, 5), v('today', 3, 5), iv('today', 5), iv('today', 6), v('today', 7, 6)))
    d.h2('8.2 What the brane sees')
    d.p('**On $S^4$** the brane at the north pole sees, at each level $l$, only the ZONAL harmonic (the one that depends on $x_4$ alone); all others '
        'vanish there. With the Gegenbauer polynomial $C_l^{(3/2)}$:')
    d.eq(r'Z_l(x_4)=\sqrt{\frac{d_l}{V}}\;\frac{C_l^{(3/2)}(\cos x_4)}{C_l^{(3/2)}(1)},\qquad C_l^{(3/2)}(1)=\frac{(l+1)(l+2)}2,\qquad \frac1{\sin^3x_4}\frac d{dx_4}\Big(\sin^3x_4\frac{dZ_l}{dx_4}\Big)=-l(l+3)Z_l,')
    d.p('normalized ($\\int_{S^4}Z_l^2=1$) and of value $\\sqrt{d_l/V}$ at the brane (section 26.4 checks $l=0,\\dots,6$ exactly). So the brane couples to '
        'ONE state per level with the strength $\\sqrt{d_l/V}$. **On $T^4$** every mode $e^{2\\pi i\\vec n\\cdot\\vec y/\\ell_\\perp}/\\sqrt V$ has the value $1/\\sqrt V$ at '
        '$y=0$; the brane couples to the combination $\\sum_{|\\vec n|^2=k}\\psi_{\\vec n}$, again one state per level, with the strength $\\sqrt{r_4(k)/V}$. '
        '**Symmetry:** the sphere has the 10 Killing vectors of $SO(5)$, $L_{ab}=X_a\\partial_b-X_b\\partial_a$; at the north pole $(0,0,0,0,r)$ the 6 with '
        '$a,b\\le4$ vanish (the brane keeps $SO(4)$) and 4 move it (broken). On the torus the brane keeps the 384 signed permutations and breaks '
        'the 4 translations — which is why Kaluza–Klein momentum is not conserved at the brane in either case.')
    d.h2('8.3 dirac16complex: zero modes on $T^4$, none on $S^4$')
    d.p('The 16 components of dirac16complex are a four-dimensional Dirac spinor times a 4-component spinor of the extra space. Its Kaluza–Klein '
        'masses are $\\sqrt{m^2+|\\lambda|^2}$ with $\\lambda$ the eigenvalues of the Dirac operator $\\not D=\\tilde\\gamma^a\\nabla_a$ of the extra space '
        '($\\tilde\\gamma_a=i\\rho_{a+3}$ Hermitian, $\\tilde\\gamma_a\\tilde\\gamma_b+\\tilde\\gamma_b\\tilde\\gamma_a=2\\delta_{ab}$, $\\rho$ the 4×4 matrices of the brane '
        'spinors of 7+1.nb). **On $T^4$** with periodic spinors the constant spinors are zero modes: for $m=0$, four massless brane Dirac fermions '
        '(section 25 of 7+1.nb). **On $S^4$** there are none: the Killing spinors')
    d.eq(r'\varepsilon_s=e^{s\frac i2x_4\tilde\gamma_1}\,e^{\frac12x_5\tilde\gamma_1\tilde\gamma_2}\,e^{\frac12x_6\tilde\gamma_2\tilde\gamma_3}\,e^{\frac12x_7\tilde\gamma_3\tilde\gamma_4}\,\varepsilon_0,\qquad \nabla_i\varepsilon_s=s\,\frac i{2r}\,e_i{}^a\tilde\gamma_a\varepsilon_s,\qquad \not D\varepsilon_s=s\,\frac{2i}r\,\varepsilon_s\qquad(s=\pm1)')
    d.p('(frame $e^a=(r,r\\sin x_4,r\\sin x_4\\sin x_5,r\\sin x_4\\sin x_5\\sin x_6)\\,dx^{a+3}$; checked exactly in section 26.4) reach the lowest value allowed by '
        'Friedrich’s bound $|\\lambda|^2\\ge\\frac{nR}{4(n-1)}=\\frac4{r^2}$. The spectrum is $\\lambda=\\pm i(l+2)/r$, $l=0,1,2,\\dots$, with the degeneracy '
        '$4\\binom{l+3}3=%s,\\dots$ for each sign (Camporesi and Higuchi); the spinor Weyl law $N(|\\lambda|\\le L/r)\\approx L^4/3$ agrees to %s at $L=1000$. '
        'The lightest dirac16complex states on $S^4$ are eight Dirac fermions of mass $\\sqrt{m^2+4/r^2}$ — with $r=r_{S^4}$, at least %s MeV.'
        % (','.join(iv('dirac', i) for i in range(6)), v('dirac', 6, 2), v('today', 4, 5)))

    # ==============================================================================================
    d.h1('9. Flat versus warped: the Randall–Sundrum radion')
    d.p('7+1.nb is UNWARPED: its bulk is a product of ordinary spacetime and the extra space. The note contrasts this with the warped model of Randall '
        'and Sundrum (RS1), in FIVE dimensions: $ds^2=e^{-2A(y)}\\eta_{\\mu\\nu}dx^\\mu dx^\\nu-dy^2$, $y\\in[-\\pi R,\\pi R]$ with $y\\simeq-y$ (an orbifold), '
        'branes at $y=0$ (UV) and $y=\\pi R$ (IR, where the Standard Model lives). Section 26.5 checks it with the conventions of section 2.')
    d.h2('9.1 The background, the tensions and the junction conditions')
    d.eq(r"G^\mu{}_\nu=\big(3A''-6A'^2\big)\delta^\mu_\nu,\qquad G^y{}_y=-6A'^2;\qquad A=k|y|:\quad \Lambda=-6k^2\ \text{(anti-de Sitter)}.")
    d.p('At the branes the slope $A\'$ jumps by $+2k$ (UV: from $-k$ to $+k$) and by $-2k$ (IR), so $A\'\'=\\pm2k\\,\\delta$; a brane of tension $f$ '
        '($T^\\mu{}_\\nu=f\\delta(y)\\delta^\\mu_\\nu$: energy $f$, pressure $-f$) balances the $\\delta$ part of $G^\\mu{}_\\nu$ (coefficient %s) if' % iv('rs1', 0))
    d.eq(r'3\cdot(\pm2k)=\kappa f:\qquad f_{\rm UV}=+\frac{6k}\kappa,\qquad f_{\rm IR}=-\frac{6k}\kappa\qquad(f\kappa/k=%s,\ %s).' % (iv('rs1', 1), iv('rs1', 2)))
    d.p('The UV brane has POSITIVE tension, the result of Randall and Sundrum, $V_{\\rm hid}=-V_{\\rm vis}=24M^3k$ (with $\\kappa=1/(4M^3)$, section 9.2). '
        'The same follows from the extrinsic curvature: with $K^\\mu{}_\\nu=\\frac12g^{\\mu\\alpha}\\partial_yg_{\\alpha\\nu}=-A\'\\delta^\\mu_\\nu$ (normal $\\partial_y$), the '
        '$\\delta$-function part of $G^\\mu{}_\\nu$ at a brane is')
    d.eq(r"[K^\mu{}_\nu]^+_--\delta^\mu_\nu[K]^+_-=-[A']+4[A']=3[A']=6k\quad\text{(UV)},\qquad \text{so}\qquad G^\mu{}_\nu\big|_\delta=\kappa T^\mu{}_\nu\big|_\delta\ \Rightarrow\ f_{\rm UV}=\frac{6k}\kappa .")
    d.p('In the signature $(-,+,+,+,+)$ of the note $G^A{}_B$ changes sign, so there the junction condition reads $[K_{\\mu\\nu}-\\hat g_{\\mu\\nu}K]^+_-=-\\kappa^2S_{\\mu\\nu}$ '
        '(section 26.5). The note states the positive UV tension first ($\\lambda_A=-\\lambda_B=6k/\\kappa_8^2$), but its Israel-junction computation uses '
        '$[K_{\\mu\\nu}-\\hat g_{\\mu\\nu}K]^+_-=+\\kappa^2S_{\\mu\\nu}$ with $S_{\\mu\\nu}=-\\lambda\\hat g_{\\mu\\nu}$ and ends with $\\lambda_{\\rm UV}=-6k/\\kappa^2$, $\\lambda_{\\rm IR}=+6k/\\kappa^2$: '
        'the wrong sign of the junction condition reverses both tensions. (Its intermediate steps, $K^\\pm_{\\mu\\nu}=\\mp k\\hat g_{\\mu\\nu}$ and '
        '$[K_{\\mu\\nu}-\\hat g_{\\mu\\nu}K]^+_-=6k\\hat g_{\\mu\\nu}$, are right.)')
    d.h2('9.2 The Planck mass, the radion and the normalizations')
    d.eq(r'M_{\rm Pl}^2=\frac1\kappa\int_{-\pi R}^{\pi R}e^{-2k|y|}dy=\frac{1-e^{-2\pi kR}}{\kappa k} .')
    d.p('Promoting $R$ to a field, $ds^2=e^{-2kT(x)|y|}g_{\\mu\\nu}dx^\\mu dx^\\nu-T(x)^2dy^2$ ($y\\in[-\\pi,\\pi]$), the bulk action gives the kinetic term '
        '(section 26.5; a total derivative removed)')
    d.eq(r'\mathcal L_{\rm kin}=\frac3{\kappa k}\,\big(\partial e^{-k\pi T}\big)^2=\frac12(\partial\mu)^2\quad\text{for}\quad \mu=f\,e^{-k\pi T},\qquad f^2=\frac6{\kappa k}\quad(f^2\kappa k=%s).' % iv('rs1', 3))
    d.p('Here $1/(2\\kappa)$ is the coefficient of $\\sqrt{|G|}R$ in the bulk action, $M_{\\rm Pl}^2/2$ that of $\\sqrt{|g|}R_4$, $\\frac12$ that of $(\\partial\\mu)^2$. '
        'The literature and the note use three normalizations:')
    d.table(['bulk action', '$\\kappa$', '$f$', '$M_{\\rm Pl}^2\\ (\\times(1-e^{-2\\pi kR}))$', 'used by'], [
        ['$-\\frac1{2\\kappa}\\int\\sqrt{|G|}R$', '$\\kappa$', '$\\sqrt{6/(\\kappa k)}$', '$1/(\\kappa k)$', 'this document, 7+1.nb'],
        ['$2M^3\\int\\sqrt{|G|}R$ (signature $(-,+,\\dots)$)', '$1/(4M^3)$', '$\\sqrt{24M^3/k}$', '$4M^3/k$ (with $\\frac{M_{\\rm Pl}^2}2R_4$)', 'Randall–Sundrum, Goldberger–Wise'],
        ['$M_5^3\\int\\sqrt{|G|}R_5$ (signature $(-,+,\\dots)$)', '$1/(2M_5^3)$', '$\\sqrt{12M_5^3/k}$', '$2M_5^3/k$', 'the note’s five-dimensional part'],
    ], widths=[0.22, 0.12, 0.16, 0.28, 0.22])
    d.p('The note’s five-dimensional part combines $M_5^3\\int\\sqrt{|G|}R_5$ with $f=\\sqrt{24M_5^3/k}$ and $M_{\\rm Pl}^2=(M_5^3/k)(1-e^{-2k\\pi\\langle T\\rangle})$, '
        'formulas of the second row (Randall and Sundrum define $M_{\\rm Pl}$ through $2M_{\\rm Pl}^2\\int\\sqrt{|g|}R_4$); in its own normalization they read '
        '$f=\\sqrt{12M_5^3/k}$ and $M_{\\rm Pl}^2=(2M_5^3/k)(1-e^{-2k\\pi\\langle T\\rangle})$. Its later version with $\\kappa_8^2$ has the right $M_{\\rm Pl}^2$ (and the right '
        'kinetic term $\\frac1{2\\kappa}\\frac6k(\\partial e^{-k\\pi T})^2$, which requires the full circle $y\\in[-\\pi,\\pi]$ although it writes $\\int_0^\\pi$) but '
        '$f=\\sqrt{12/(\\kappa k)}$ instead of $\\sqrt{6/(\\kappa k)}$.')
    d.h2('9.3 Goldberger–Wise stabilization and the mass of the warped radion')
    d.p('A bulk scalar $\\Phi(y)$ of mass $m$ with the brane values $\\Phi(0)=v_A$, $\\Phi(\\pi T)=v_B$ obeys, between the branes ($\\sqrt{|G|}=e^{-4ky}$, '
        '$G^{yy}=-1$),')
    d.eq(r"\Phi''-4k\Phi'-m^2\Phi=0,\qquad \Phi=e^{2ky}\big(C_1e^{\nu ky}+C_2e^{-\nu ky}\big),\qquad \nu=\sqrt{4+\frac{m^2}{k^2}}=2+\epsilon+O(m^4),\quad \epsilon=\frac{m^2}{4k^2},")
    d.p('and Goldberger and Wise find the potential $V\\approx k\\epsilon v_A^2+4ke^{-4k\\pi T}(v_B-v_Ae^{-\\epsilon k\\pi T})^2$, i.e. with $\\mu=fe^{-k\\pi T}$')
    d.eq(r'V(\mu)=4k\Big(\frac\mu f\Big)^4\Big[v_B-v_A\Big(\frac\mu f\Big)^\epsilon\Big]^2+{\rm const}.')
    d.p('Section 26.5 checks: $V\'(\\langle\\mu\\rangle)=0$ at $(\\langle\\mu\\rangle/f)^\\epsilon=v_B/v_A$, i.e. $k\\pi\\langle T\\rangle=(4k^2/m^2)\\ln(v_A/v_B)$ (the note’s value); '
        '$V\'\'(\\langle\\mu\\rangle)=8k\\epsilon^2v_B^2\\langle\\mu\\rangle^2/f^4$ (the note’s algebra is right); and with $f^2=6/(\\kappa k)$')
    d.eq(r"m_r^2=V''(\langle\mu\rangle)=\frac43\,\kappa k^2\epsilon^2v_B^2\Big(\frac{\langle\mu\rangle}f\Big)^2=\frac{k^2v_B^2\epsilon^2}{3M^3}\,e^{-2k\pi\langle T\rangle}\quad(\kappa=1/(4M^3)),")
    d.p('the result of Goldberger and Wise (coefficient %s; the note’s $\\frac23$, coefficient %s, follows from its $f^2=12/(\\kappa k)$). Goldberger and Wise add '
        'that a more careful treatment of the $\\epsilon$ terms turns $\\epsilon^2$ into $\\epsilon^{3/2}$.' % (v('gw', 0, 4), v('gw', 1, 4)))
    d.h2('9.4 Couplings: TeV-strong versus Planck-weak')
    d.p('On the IR brane $h=(\\mu/f)^2g$: the warped radion couples to brane matter with $1/\\langle\\mu\\rangle$ ($\\mathcal L=(r/\\langle\\mu\\rangle)T^\\mu{}_\\mu$ for '
        '$\\mu=\\langle\\mu\\rangle+r$), the flat radion of 7+1 with $1/(\\sqrt3M_{\\rm Pl})$. For $\\langle\\mu\\rangle=3$ TeV the warped coupling is stronger by')
    d.eq(r'\frac{\sqrt3\,M_{\rm Pl}}{3\ {\rm TeV}}=%s .' % v('strength', 0, 5))
    d.h2('9.5 Warping in eight dimensions')
    d.p('The note also offers the equations $3A\'\'+6A\'^2=-\\kappa_8^2\\Lambda_8$, $6A\'^2=-\\kappa_8^2\\Lambda_8$ for an eight-dimensional warped metric with '
        'four extra dimensions. These are the five-dimensional equations. For $ds^2=e^{-2A(y)}\\eta-dy^2-d\\vec z^{\\,2}$ (warping along one of the four '
        'extra directions, $\\vec z$ the other three) section 26.5 finds')
    d.eq(r"G^\mu{}_\nu=3A''-6A'^2,\qquad G^y{}_y=-6A'^2,\qquad G^z{}_z=4A''-10A'^2,")
    d.p('and with only a cosmological constant all eight must be equal, which forces $A\'\'=0$ and $A\'=0$: there is no warped solution of this form. '
        'Warped compactifications with several extra dimensions need other sources (fluxes, several branes); 7+1.nb does not use them.')

    # ==============================================================================================
    d.h1('10. The radion through the three regimes of 7+1')
    d.p('7+1.nb follows the size of the auxiliary torus — the radion — through the history of its universe (sections 14 and 20–23):')
    d.ol(['**Primordial (Kasner) regime:** near $x_0=0$ ordinary space expands while the torus contracts; in Einstein gravity $a\\propto\\tau^{p_1}$, '
          '$b\\propto\\tau^{q_1}$ with $p_1=%s$, $q_1=%s$: the radion decreases logarithmically, $\\beta=q_1\\ln\\tau+$const.' % (g(pq, 0, 6), g(pq, 1, 6)),
          '**Without a stabilizer** a gas of dirac16complex makes the torus re-expand, $b\\propto\\tau^{2/5}$ (section 21.3: $\\tau H_b=%s$): the radion '
          'runs to $+\\infty$ — decompactification.' % g(late, 1, 6),
          '**Capture:** with the stabilizer $U$ the radion is caught when the expansion rate falls below $m_r$ and oscillates, '
          '$\\beta\\simeq A\\sin(m_r\\tau+\\vartheta)/(m_r(\\tau-\\tau_E))$ (section 22.1, fit $A=%s$, $\\vartheta=%s$). Its oscillation energy is four-dimensional '
          'matter; the radion decays mostly into Kaluza–Klein pairs of dirac16complex (section 22.2).' % (g(capfit, 0, 4), g(capfit, 1, 4)),
          '**Today:** frozen at a displaced minimum, $\\beta_{\\rm eq}=%s$ from the cosmological constant and matter, $%s$ from a brane tension $f_W=M_8^4$ '
          '(section 22.4, $m_r=10$ GeV): $G_4=G_8/V$ is constant to that accuracy.' % (g(radnow, 0, 2), g(radnow, 1, 2)),
          '**Far future:** in the de Sitter phase the radion relaxes to $3m_r^2\\beta_{\\rm eq}=3H^2-12\\alpha_2H^4$, of order $H_\\infty^2/m_r^2$ (section 23.2); '
          'without the stabilizer eight-dimensional de Sitter space would let the torus inflate.'])
    d.p('On a sphere instead of the torus the same history would need the stiffer stabilizer of section 6.4, and the primordial contraction would '
        'meet the curvature potential $-6M_{\\rm Pl}^2e^{-6\\beta}/r_0^2$, which accelerates the collapse.')

    # ==============================================================================================
    d.h1('11. The note, statement by statement')
    d.table(['#', 'statement of the note (paraphrased)', 'verdict', 'here'], [
        ['1', 'Kaluza–Klein ansatz $e^{2\\alpha\\phi}g+e^{2\\beta\\phi}\\gamma$; Einstein frame fixes $\\alpha,\\beta$', 'correct ($2\\alpha+n\\beta=0$)', '§4.1–4.2'],
        ['2', '$\\alpha=-\\sqrt{n/(2(n+2))}$, $\\beta=\\sqrt{2/(n(n+2))}$ give $\\frac{V_n}{2\\kappa^2}[R-\\frac12(\\partial\\phi)^2]$', 'factor 2: they give $R-(\\partial\\phi)^2$; '
         'for $\\frac12$: $\\beta=1/\\sqrt{n(n+2)}$', '§4.5'],
        ['3', '$V_{\\rm phys}=V_ne^{n\\beta\\phi}$', 'correct', '§4.4'],
        ['4', 'without a potential the radion is a modulus; a massless radion mediates a fifth force', 'correct on $T^4$; on $S^4$ the curvature gives a potential; '
         'strength $\\frac23$', '§6.2, §7.2'],
        ['5', 'eight dimensions: $\\alpha=-1/\\sqrt3$, $\\beta=1/\\sqrt{12}$, $\\frac{M_{\\rm Pl}^2}2R-\\frac12(\\partial\\phi)^2$, $V=V_0e^{(2/\\sqrt3)\\phi}$', 'correct with $\\phi$ '
         'in units of $M_{\\rm Pl}$ in the exponent', '§4.5'],
        ['6', 'Goldberger–Wise in eight dimensions: $V=\\int\\sqrt\\gamma e^{4\\beta\\phi}[\\frac12e^{-2\\beta\\phi}(\\nabla\\Phi)^2+\\frac12m_8^2\\Phi^2]$', 'missing factor $e^{-8\\beta\\phi}$: '
         'gradient $e^{-6\\beta}$, mass $e^{-4\\beta}$', '§6.8'],
        ['7', '$m_r\\sim(m_8/M_8)^2M_{4D}$; force $\\propto e^{-m_rr}/r^2$', 'estimate not derived; in 7+1 $m_r^2=\\kappa K_U/12$ ($T^4$), $\\kappa K_U/12-2/r_0^2$ ($S^4$); '
         'Yukawa suppression right (the force is $\\propto e^{-m_rr}(1+m_rr)/r^2$)', '§6.3–6.4, §7.2'],
        ['8', 'RS1: orbifold, warp $e^{-2kT|y|}$, $\\langle T\\rangle=R$, TeV scale, coupling $1/\\langle\\mu\\rangle$', 'correct', '§9'],
        ['9', 'RS1: $S_5=M_5^3\\int R_5$ with $f=\\sqrt{24M_5^3/k}$, $M_{\\rm Pl}^2=(M_5^3/k)(1-e^{-2k\\pi\\langle T\\rangle})$', 'mixed normalizations: $\\sqrt{12M_5^3/k}$, '
         '$2M_5^3/k$ in its own', '§9.2'],
        ['10', 'warped eight dimensions: $3A\'\'+6A\'^2=-\\kappa^2\\Lambda$, $6A\'^2=-\\kappa^2\\Lambda$, $A=k|y|$, AdS$_8$', 'these are five-dimensional; in 8D '
         '$G^z{}_z=4A\'\'-10A\'^2$, no solution', '§9.5'],
        ['11', 'tensions $\\lambda_A=-\\lambda_B=6k/\\kappa_8^2$', 'correct (UV positive)', '§9.1'],
        ['12', 'Israel junction: $\\lambda_{\\rm UV}=-6k/\\kappa_8^2$, $\\lambda_{\\rm IR}=+6k/\\kappa_8^2$', 'signs reversed (the junction condition needs $-\\kappa^2S_{\\mu\\nu}$)', '§9.1'],
        ['13', '$S_{\\rm eff}=\\frac1{2\\kappa}\\int[\\frac1k(1-e^{-2k\\pi T})R_4+\\frac6k(\\partial e^{-k\\pi T})^2]$, $M_{\\rm Pl}^2=\\frac{1-e^{-2k\\pi\\langle T\\rangle}}{\\kappa k}$',
         'correct over $y\\in[-\\pi,\\pi]$ (the note writes $\\int_0^\\pi$)', '§9.2'],
        ['14', '$f_\\mu=\\sqrt{12/(\\kappa_8^2k)}$', '$\\sqrt{6/(\\kappa k)}$', '§9.2'],
        ['15', 'Goldberger–Wise: bulk equation, profile, $\\nu\\approx2+\\epsilon$, $V(T)$, $k\\pi\\langle T\\rangle=(4k^2/m^2)\\ln(v_A/v_B)$, $V\'\'$', 'correct ($V(T)$ quoted from '
         'Goldberger–Wise)', '§9.3'],
        ['16', '$m_r^2=\\frac23\\kappa k^2\\epsilon^2v_B^2(\\langle\\mu\\rangle/f)^2$', '$\\frac43$ (from $f$); Goldberger–Wise’s result', '§9.3'],
        ['17', 'Higgs–radion: $-\\xi\\int\\sqrt{-g}R\\,H^\\dagger H$; kinetic mixing $-6\\xi\\gamma\\,\\partial h\\cdot\\partial r$', 'correct; the radion kinetic term also gets $6\\xi\\gamma^2$', '§7.3'],
        ['18', '$Z^2=1+6\\xi\\gamma^2(1-6\\xi)$, the shift, $\\tan2\\theta$, $C_h$, $C_r$', 'correct; the displayed rotation is the inverse', '§7.3'],
        ['19', 'trace-anomaly couplings, $\\Gamma(h\\to\\gamma\\gamma)$, $\\Gamma(h\\to gg)$ ratios', 'structure correct; values quoted', '§7.3'],
        ['20', 'LHC bounds $\\langle\\mu\\rangle>2.5$–$3$ TeV, $-0.1<\\xi<0.4$', 'quoted, not checked; irrelevant for 7+1 ($\\gamma=%s$)' % v('ew', 2, 2), '§7.3'],
    ], widths=[0.055, 0.45, 0.375, 0.12], small=True)

    # ==============================================================================================
    d.h1('12. Validity and limitations')
    d.ul(['The radion here is the overall size only. The shape moduli of $T^4$ (nine), the Kaluza–Klein vectors and the deformations of $S^4$ are not '
          'treated; on $S^4$ the $l=2$ deformations are massive by the curvature, on $T^4$ they are moduli.',
          'The reduction is checked for homogeneous fields $N(x_0)$, $a(x_0)$, $\\beta(x_0)$; covariance extends it to $\\beta(x)$ and $g_E(x)$, as the '
          'canonical kinetic term $\\frac12g_E^{\\mu\\nu}\\partial_\\mu\\phi\\partial_\\nu\\phi$ requires.',
          'The 4-form flux of section 6.6 is an illustration: 7+1.nb has no such field.',
          'The stabilizer is the phenomenological $U(b)$ of section 20; the Goldberger–Wise mechanism is analyzed only in the warped five-dimensional '
          'model (section 9.3), where it is quoted and its algebra checked.',
          'The Higgs–radion analysis is at the quadratic order; the trace-anomaly coefficients and the LHC bounds are the note’s.',
          'The numbers today assume $M_8=10$ TeV and $M_{\\rm Pl}=2.435\\times10^{18}$ GeV.'])

    # ==============================================================================================
    d.h1('13. Verification')
    d.p('Every worked example of this document is a check of section 26 of 7+1.nb (Wolfram Language 15.0.1; evaluated in a fresh kernel, %s message '
        'cells) and of the independent Python program tools/ref_radion.py (sympy, numpy, mpmath; its own curvature routine, Euler–Lagrange operators, '
        'lattice sieve and 60-digit arithmetic). The checks of section 26:' % D['log'].get('message cells', '?'))
    ck = D['checks'].get('rd', [])
    d.table(['#', 'check', 'result', 'section'], [[str(i + 1), '`' + c[0].replace('`', "'") + '`', c[1], (c[3][:4] if c[3] else c[2][:3])]
                                                 for i, c in enumerate(ck)], widths=[0.05, 0.77, 0.08, 0.10], small=True)
    d.p('The Python program’s boolean checks:')
    d.table(['#', 'check', 'result'], [[str(i + 1), '`' + k.replace('`', "'") + '`', vv] for i, (k, vv) in enumerate(rb)], widths=[0.05, 0.83, 0.12], small=True)
    d.p('The numbers printed by both programs (largest relative difference per group; integers must agree exactly):')
    rows = []
    for lab, a, b, tol, r in cmp_:
        rows.append([lab, str(len(a)), fmt(r, 2) if r is not None else '—', fmt(tol, 1) if tol else 'exact'])
    d.table(['quantity', 'values', 'max. relative difference', 'tolerance'], rows, widths=[0.52, 0.1, 0.22, 0.16], small=True)
    d.p('The results quoted from the other sections of 7+1.nb rest on these checks of the notebook, all evaluated in the same run:')
    d.table(['#', 'check', 'result', 'section'], basis_checks(D, BASIS), widths=[0.05, 0.77, 0.08, 0.10], small=True)

